"""Evaluate and render the three-session failure-to-hold false-breakout rejection method."""
from __future__ import annotations
import argparse,json
from datetime import timedelta
from pathlib import Path
import pandas as pd
def metrics(frame):
 complete=frame[frame.confirmation_complete.astype(str).str.lower().eq("true")&frame.future20.notna()].copy();false=~complete.direct_true.astype(str).str.lower().eq("true");held=complete.held_abs_3.astype(str).str.lower().eq("true")&complete.held_rel_3.astype(str).str.lower().eq("true");rejected=~held;tp=int((rejected&false).sum());fp=int((rejected&~false).sum());fn=int((held&false).sum());tn=int((held&~false).sum());return {"signals":len(complete),"rejected":int(rejected.sum()),"false_breakouts":int(false.sum()),"true_breakouts":int((~false).sum()),"true_false_rejections":tp,"false_rejections_of_true":fp,"false_detection_precision":tp/(tp+fp) if tp+fp else 0.0,"false_detection_recall":tp/(tp+fn) if tp+fn else 0.0,"true_breakout_retention":tn/(tn+fp) if tn+fp else 0.0,"survivor_true_rate":tn/(tn+fn) if tn+fn else 0.0}
def run(features_path,out_json,out_md,current_json,current_md):
 x=pd.read_csv(features_path);periods={name:metrics(x[x.year.between(a,b)]) for name,a,b in [("2018-2022",2018,2022),("2023-2024",2023,2024),("2025",2025,2025)]};overall=metrics(x[x.year.between(2018,2025)]);checks={"validation_rejections":periods["2023-2024"]["rejected"]>=30,"holdout_rejections":periods["2025"]["rejected"]>=30,"overall_precision":overall["false_detection_precision"]>=.90,"validation_precision":periods["2023-2024"]["false_detection_precision"]>=.90,"holdout_precision":periods["2025"]["false_detection_precision"]>=.90,"overall_recall":overall["false_detection_recall"]>=.50,"validation_recall":periods["2023-2024"]["false_detection_recall"]>=.50,"holdout_recall":periods["2025"]["false_detection_recall"]>=.50,"true_retention":overall["true_breakout_retention"]>=.55};payload={"study":"a-share-false-breakout-rejection-v4","method":"reject if either absolute or relative index closes below D0 breakout level during D1-D3","label":"false unless D0 forward10>=4%, forward20>=8%, relative20>=4%","overall":overall,"periods":periods,"checks":checks,"verdict":"GO-RISK-FILTER" if all(checks.values()) else "NO-GO","trade_authorized":False};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2)+"\n");lines=["# A股假突破识别V4结果","",f"- verdict: **{payload['verdict']}**",f"- overall precision/recall: {overall['false_detection_precision']:.2%} / {overall['false_detection_recall']:.2%}",f"- 2023-2024 precision/recall: {periods['2023-2024']['false_detection_precision']:.2%} / {periods['2023-2024']['false_detection_recall']:.2%}",f"- 2025 precision/recall: {periods['2025']['false_detection_precision']:.2%} / {periods['2025']['false_detection_recall']:.2%}",f"- true-breakout retention: {overall['true_breakout_retention']:.2%}","- trade authorized: **NO**"];Path(out_md).write_text("\n".join(lines)+"\n");latest=pd.to_datetime(x.signal_date).max();current=x[pd.to_datetime(x.signal_date).ge(latest-timedelta(days=35))].copy();complete=current.confirmation_complete.astype(str).str.lower().eq("true");held=current.held_abs_3.astype(str).str.lower().eq("true")&current.held_rel_3.astype(str).str.lower().eq("true");current["status"]="PENDING_D3";current.loc[complete&held,"status"]="BREAKOUT_HELD";current.loc[complete&~held,"status"]="FALSE_BREAKOUT_REJECTED";records=current[["signal_date","sector","status","price_breadth","relative20"]].sort_values(["signal_date","sector"]).to_dict("records");current_payload={"as_of":latest.date().isoformat(),"method_verdict":payload["verdict"],"trade_authorized":False,"signals":records};Path(current_json).write_text(json.dumps(current_payload,ensure_ascii=False,indent=2)+"\n");current_lines=["# A股假突破当前识别","",f"- as of: {latest.date().isoformat()}",f"- method: **{payload['verdict']}**","- trade authorized: **NO**",""]+[f"- {r['signal_date']} {r['sector']}: {r['status']}" for r in records];Path(current_md).write_text("\n".join(current_lines)+"\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--features",default="overall/a-share-sector-false-breakout-features.csv");p.add_argument("--out-json",default="overall/a-share-false-breakout-rejection-v4-result.json");p.add_argument("--out-md",default="overall/a-share-false-breakout-rejection-v4-result.md");p.add_argument("--current-json",default="overall/a-share-false-breakout-current.json");p.add_argument("--current-md",default="overall/a-share-false-breakout-current.md");a=p.parse_args(argv);run(a.features,a.out_json,a.out_md,a.current_json,a.current_md);return 0
if __name__=="__main__":raise SystemExit(main())
